 g=arena();ball=add(g);drop=ready(g,PickupKind::Flower,Vec(40,0));ticks(g,5);verify(g.flower_count()==1,"flower outside initial collision radius remains");g.improve_flowers(5,true);ticks(g,20);verify(g.flower_count()==0&&g.world.balls[ball].def.base_score==7,"growing flower can reach stationary ball while simulation is otherwise idle");
